style.css:
@-moz-document url-prefix("https://www.youtube.com") {
/* ---- ЦВЕТОВАЯ ПАЛИТРА ---- */
  :root {
    --aero-soft-light-blue: #d0ecf7;  /* Нежно-голубой для сайдбара */
    --aero-soft-blue: #bce3f2;        /* Нежно-синий для поиска */
    --aero-dark-blue: #0c6180;        /* Темно-синий для текста (контрастный) */
    --aero-white-glass: rgba(255, 255, 255, 0.6);
  }

  /* ---- ФОН ---- */
  #page-manager, ytd-app, body {
    background-color: #e0f2f9 !important;
    background-image: url('https://i.pinimg.com/736x/32/13/71/32137163c5bed751457e2335903ec013.jpg') !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* ---- ВЕРХНЯЯ ПАНЕЛЬ ---- */
  #masthead, ytd-masthead {
    background: var(--aero-white-glass) !important;
    backdrop-filter: blur(8px) !important;
  }

  /* ---- САЙДБАР (МЕНЮ ПОДПИСОК) ---- */
  #guide, ytd-guide-renderer {
    background: var(--aero-soft-light-blue) !important;
  }

  /* ---- ★ ТЕКСТ В САЙДБАРЕ (СИНИЙ И КОНТРАСТНЫЙ) ★ ---- */
  /* Заголовки ("Подписки", "Вы") */
  #guide #guide-title, 
  #guide ytd-guide-collapsible-entry-renderer #guide-title {
    color: var(--aero-dark-blue) !important;
  }

  /* Пункты меню ("Главная", "Shorts", имена каналов "EroxBlox" и т.д.) */
  #guide ytd-guide-entry-renderer #title,
  #guide ytd-guide-entry-renderer #channel-name,
  #guide ytd-guide-entry-renderer ytd-formatted-string {
    color: var(--aero-dark-blue) !important;
    font-weight: 600 !important; /* Сделал шрифт чуть жирнее для читаемости */
  }

  /* Иконки в сайдбаре (домик, огонёк, аватарки, стрелочки) */
  #guide ytd-guide-entry-renderer #guide-icon,
  #guide ytd-guide-entry-renderer ytd-icon {
    fill: var(--aero-dark-blue) !important;
    color: var(--aero-dark-blue) !important;
  }

  /* ---- СТРОКА ПОИСКА ---- */
  #search-input, .ytSearchboxComponentInput, ytd-searchbox {
    background: var(--aero-soft-blue) !important;
    border-radius: 25px !important;
    color: var(--aero-dark-blue) !important;
  }

  /* ---- ОСТАЛЬНЫЕ ТЕКСТЫ ---- */
  h1, #channel-name, .ytd-channel-name, .yt-formatted-string {
    color: var(--aero-dark-blue) !important;
  }

  /* ---- КНОПКИ И ВИДЕО ---- */
  #progress-bar {
    background: linear-gradient(90deg, var(--aero-soft-blue), var(--aero-dark-blue)) !important;
  }
  ytd-rich-item-renderer {
    background: rgba(255, 255, 255, 0.8) !important;
    border-radius: 20px !important;
  }
}
